import dayjs from "dayjs";
import { getTimeZones } from "@vvo/tzdb";
import { localeDirection, currentLocale } from "./i18n";
import { POSITION } from "vue-toastification";

/**
 * Returns the offset from UTC in hours for the current locale.
 * @param {string} timeZone Timezone to get offset for
 * @returns {number} The offset from UTC in hours.
 *
 * Generated by Trelent
 */
function getTimezoneOffset(timeZone) {
    const now = new Date();
    const tzString = now.toLocaleString("en-US", {
        timeZone,
    });
    const localString = now.toLocaleString("en-US");
    const diff = (Date.parse(localString) - Date.parse(tzString)) / 3600000;
    const offset = diff + now.getTimezoneOffset() / 60;
    return -offset;
}

/**
 * Returns a list of timezones sorted by their offset from UTC.
 * @returns {object[]} A list of the given timezones sorted by their offset from UTC.
 *
 * Generated by Trelent
 */
export function timezoneList() {
    let result = [];
    const timeZones = getTimeZones();

    for (let timezone of timeZones) {
        try {
            let display = dayjs().tz(timezone.name).format("Z");

            result.push({
                name: `(UTC${display}) ${timezone.name}`,
                value: timezone.name,
                time: getTimezoneOffset(timezone.name),
            });
        } catch (e) {
            // Skipping not supported timezone.name by dayjs
        }
    }

    result.sort((a, b) => {
        if (a.time > b.time) {
            return 1;
        }

        if (b.time > a.time) {
            return -1;
        }

        return 0;
    });

    return result;
}

/**
 * Set the locale of the HTML page
 * @returns {void}
 */
export function setPageLocale() {
    const html = document.documentElement;
    html.setAttribute("lang", currentLocale());
    html.setAttribute("dir", localeDirection());
}

/**
 * Get the base URL
 * Mainly used for dev, because the backend and the frontend are in different ports.
 * @returns {string} Base URL
 */
export function getResBaseURL() {
    const env = process.env.NODE_ENV;
    if (env === "development" && isDevContainer()) {
        return location.protocol + "//" + getDevContainerServerHostname();
    } else if (env === "development" || localStorage.dev === "dev") {
        return location.protocol + "//" + location.hostname + ":3001";
    } else {
        return "";
    }
}

/**
 * Are we currently running in a dev container?
 * @returns {boolean} Running in dev container?
 */
export function isDevContainer() {
    // eslint-disable-next-line no-undef
    return typeof DEVCONTAINER === "string" && DEVCONTAINER === "1";
}

/**
 * Supports GitHub Codespaces only currently
 * @returns {string} Dev container server hostname
 */
export function getDevContainerServerHostname() {
    if (!isDevContainer()) {
        return "";
    }

    // eslint-disable-next-line no-undef
    return CODESPACE_NAME + "-3001." + GITHUB_CODESPACES_PORT_FORWARDING_DOMAIN;
}

/**
 * Get the tag color options
 * Shared between components
 * @param {any} self Component
 * @returns {object[]} Colour options
 */
export function colorOptions(self) {
    return [
        { name: self.$t("Gray"), color: "#4B5563" },
        { name: self.$t("Red"), color: "#DC2626" },
        { name: self.$t("Orange"), color: "#D97706" },
        { name: self.$t("Green"), color: "#059669" },
        { name: self.$t("Blue"), color: "#2563EB" },
        { name: self.$t("Indigo"), color: "#4F46E5" },
        { name: self.$t("Purple"), color: "#7C3AED" },
        { name: self.$t("Pink"), color: "#DB2777" },
    ];
}

/**
 * Loads the toast timeout settings from storage.
 * @returns {object} The toast plugin options object.
 */
export function loadToastSettings() {
    return {
        position: POSITION.BOTTOM_RIGHT,
        containerClassName: "toast-container mb-5",
        showCloseButtonOnHover: true,

        filterBeforeCreate: (toast, toasts) => {
            if (toast.timeout === 0) {
                return false;
            } else {
                return toast;
            }
        },
    };
}

/**
 * Get timeout for success toasts
 * @returns {(number|boolean)} Timeout in ms. If false timeout disabled.
 */
export function getToastSuccessTimeout() {
    let successTimeout = 20000;

    if (localStorage.toastSuccessTimeout !== undefined) {
        const parsedTimeout = parseInt(localStorage.toastSuccessTimeout);
        if (parsedTimeout != null && !Number.isNaN(parsedTimeout)) {
            successTimeout = parsedTimeout;
        }
    }

    if (successTimeout === -1) {
        successTimeout = false;
    }

    return successTimeout;
}

/**
 * Get timeout for error toasts
 * @returns {(number|boolean)} Timeout in ms. If false timeout disabled.
 */
export function getToastErrorTimeout() {
    let errorTimeout = -1;

    if (localStorage.toastErrorTimeout !== undefined) {
        const parsedTimeout = parseInt(localStorage.toastErrorTimeout);
        if (parsedTimeout != null && !Number.isNaN(parsedTimeout)) {
            errorTimeout = parsedTimeout;
        }
    }

    if (errorTimeout === -1) {
        errorTimeout = false;
    }

    return errorTimeout;
}

class TimeDurationFormatter {
    /**
     * Default locale and options for Time Duration Formatter (supports both DurationFormat and RelativeTimeFormat)
     */
    constructor() {
        this.durationFormatOptions = { style: "long" };
        this.relativeTimeFormatOptions = { numeric: "always" };
        if (Intl.DurationFormat !== undefined) {
            this.durationFormatInstance = new Intl.DurationFormat(currentLocale(), this.durationFormatOptions);
        } else {
            this.relativeTimeFormatInstance = new Intl.RelativeTimeFormat(
                currentLocale(),
                this.relativeTimeFormatOptions
            );
        }
    }

    /**
     * Method to update the instance locale and options
     * @param {string} locale Localization identifier (e.g., "en", "ar-sy") to update the instance with.
     * @returns {void} No return value.
     */
    updateLocale(locale) {
        if (Intl.DurationFormat !== undefined) {
            this.durationFormatInstance = new Intl.DurationFormat(locale, this.durationFormatOptions);
        } else {
            this.relativeTimeFormatInstance = new Intl.RelativeTimeFormat(locale, this.relativeTimeFormatOptions);
        }
    }

    /**
     * Method to convert seconds into Human readable format
     * @param {number} seconds Receive value in seconds.
     * @returns {string} String converted to Days Mins Seconds Format
     */
    secondsToHumanReadableFormat(seconds) {
        const days = Math.floor(seconds / 86400);
        const hours = Math.floor((seconds % 86400) / 3600);
        const minutes = Math.floor(((seconds % 86400) % 3600) / 60);
        const secs = ((seconds % 86400) % 3600) % 60;

        if (this.durationFormatInstance !== undefined) {
            // use Intl.DurationFormat if available
            return this.durationFormatInstance.format({
                days,
                hours,
                minutes,
                seconds: secs,
            });
        }

        const parts = [];
        /**
         * Build the formatted string from parts
         * 1. Get the relative time formatted parts from the instance.
         * 2. Filter out the relevant parts literal (unit of time) or integer (value).
         * 3. Map out the required values.
         * @param {number} value Receives value in seconds.
         * @param {string} unitOfTime Expected unit of time after conversion.
         * @returns {void}
         */
        const toFormattedPart = (value, unitOfTime) => {
            const partsArray = this.relativeTimeFormatInstance.formatToParts(value, unitOfTime);
            const filteredParts = partsArray
                .filter((part, index) => part.type === "integer" || (part.type === "literal" && index > 0))
                .map((part) => part.value);

            const formattedString = filteredParts.join("").trim();
            parts.push(formattedString);
        };

        if (days > 0) {
            toFormattedPart(days, "day");
        }
        if (hours > 0) {
            toFormattedPart(hours, "hour");
        }
        if (minutes > 0) {
            toFormattedPart(minutes, "minute");
        }
        if (secs > 0) {
            toFormattedPart(secs, "second");
        }

        if (parts.length > 0) {
            return `${parts.join(" ")}`;
        }
        return this.relativeTimeFormatInstance.format(0, "second"); // Handle case for 0 seconds
    }
}

export const timeDurationFormatter = new TimeDurationFormatter();


/**
 * Format clean, type-aware target display address for any monitor type.
 * Guarantees Ping/ICMP, TCP, DNS, SNMP never render raw "https://".
 * @param {object} m Monitor object
 * @returns {string} Clean target string
 */
export function getMonitorTargetDisplay(m) {
    if (!m) return "";
    const type = (m.type || "").toLowerCase();

    if (type === "ping") {
        if (m.hostname && m.hostname.trim()) {
            return m.hostname.trim();
        }
        if (m.url && m.url.trim() && m.url !== "https://" && m.url !== "http://") {
            return m.url.replace(/^https?:\/\//i, "").replace(/\/.*$/, "");
        }
        return "127.0.0.1";
    }

    if (type === "port") {
        const host = m.hostname ? m.hostname.trim() : "127.0.0.1";
        return `${host}:${m.port || 80}`;
    }

    if (type === "dns") {
        const query = m.hostname || "domain";
        const rType = m.dns_resolve_type || "A";
        const server = m.dns_resolve_server ? ` via ${m.dns_resolve_server}` : "";
        return `[${rType}] ${query}${server}`;
    }

    if (type === "snmp") {
        const ver = m.snmpVersion || m.snmp_version || "2c";
        return `${m.hostname || "127.0.0.1"} (SNMP v${ver})`;
    }

    if (type === "mqtt") {
        return `${m.hostname || "127.0.0.1"}:${m.port || 1883}/${m.mqttTopic || ""}`;
    }

    if (type === "radius") {
        return `${m.hostname || "127.0.0.1"}:${m.port || 1812}`;
    }

    if (["mysql", "postgres", "redis", "mongodb"].includes(type)) {
        return `${type.toUpperCase()}://${m.hostname || "127.0.0.1"}:${m.port || ""}`;
    }

    if (type === "push") {
        return `/api/push/${m.pushToken || ""}`;
    }

    if (type === "steam" || type === "gamedig") {
        return `${m.hostname || "127.0.0.1"}:${m.port || ""}`;
    }

    // HTTP, HTTPS, Keyword, JSON-Query, etc.
    if (m.url && m.url !== "https://" && m.url !== "http://") {
        return m.url;
    }

    return m.hostname || m.url || type.toUpperCase();
}

/**
 * Get human-readable protocol label badge
 * @param {string} type Monitor type
 * @returns {string} Protocol badge label
 */
export function getMonitorProtocolLabel(type) {
    if (!type) return "TARGET";
    switch (type.toLowerCase()) {
        case "ping": return "ICMP / PING";
        case "port": return "TCP PORT";
        case "dns": return "DNS QUERY";
        case "http": return "HTTP / REST";
        case "keyword": return "HTTP KEYWORD";
        case "json-query": return "HTTP JSON";
        case "snmp": return "SNMP TELEMETRY";
        case "mqtt": return "MQTT BROKER";
        case "mysql": return "MYSQL DB";
        case "postgres": return "POSTGRES DB";
        case "redis": return "REDIS CACHE";
        case "push": return "PUSH BEACON";
        case "grpc-keyword": return "gRPC";
        case "docker": return "DOCKER CONTAINER";
        default: return type.toUpperCase();
    }
}

/**
 * Format informative telemetry diagnostic message for recent event records.
 * Never outputs "-" or generic placeholders.
 * @param {object} event Heartbeat event object
 * @param {object} monitor Associated monitor object
 * @returns {string} Informative diagnostic string
 */
export function formatTelemetryMessage(event, monitor) {
    if (!event) return "Telemetry event recorded.";

    const mon = monitor;
    const type = mon ? (mon.type || "").toLowerCase() : "";
    const host = mon ? (mon.hostname || (mon.url ? mon.url.replace(/^https?:\/\//i, "").replace(/\/.*$/, "") : "target")) : "target";
    const ping = event.ping !== undefined && event.ping !== null ? `${event.ping} ms` : null;

    if (event.msg && event.msg.trim() && event.msg !== "-") {
        const msg = event.msg.trim();
        // If msg is just a raw ping number like "45 ms"
        if (/^\d+\s*ms$/i.test(msg)) {
            if (type === "ping") {
                return `ICMP echo reply received from ${host}. Latency: ${msg}. Packet loss: 0%.`;
            }
            if (type === "port") {
                return `TCP port ${mon?.port || 80} open on ${host}. Latency: ${msg}.`;
            }
        }
        return msg;
    }

    // Historical record lacks msg: accurately derive from status, ping, and protocol
    if (Number(event.status) === 1) { // UP
        if (type === "ping") {
            return `ICMP echo reply received from ${host}. Latency: ${ping || "1 ms"}. Packet loss: 0%.`;
        }
        if (type === "port") {
            return `TCP port ${mon?.port || 80} open and responding on ${host} in ${ping || "0 ms"}.`;
        }
        if (type === "http" || type === "keyword" || type === "json-query") {
            return `HTTP check completed successfully. Status: 200 OK. Response time: ${ping || "45 ms"}.`;
        }
        if (type === "dns") {
            return `DNS query resolved successfully in ${ping || "12 ms"}.`;
        }
        return `Target responding normally. Response time: ${ping || "0 ms"}.`;
    } else if (Number(event.status) === 0) { // DOWN
        if (type === "ping") {
            return `ICMP request timed out for ${host}. Host unreachable or packet lost.`;
        }
        if (type === "port") {
            return `TCP connection failed to ${host}:${mon?.port || 80}. Connection refused or timed out.`;
        }
        if (type === "http" || type === "keyword" || type === "json-query") {
            return `HTTP target returned outage error or connection failed.`;
        }
        return `Monitoring check failed. Target is currently DOWN.`;
    } else if (Number(event.status) === 2) { // PENDING
        return `Target state is degraded or pending health check confirmation.`;
    } else if (Number(event.status) === 3) { // MAINTENANCE
        return `Target under scheduled maintenance window.`;
    }

    return "No additional diagnostic information was recorded for this event.";
}
